  useEffect(() => {
    previousItemsRef.current = items;
  }, [items]);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      wasDragging.current = isDragging;
    }, 100);

    return () => clearTimeout(timeoutId);
